package com.autoreview.cutter;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import com.arthenica.ffmpegkit.*;
public class MainActivity extends Activity {
 ArrayList<File> videos=new ArrayList<>(),audios=new ArrayList<>(); TextView status, counter, percent, stage; ProgressBar bar; Button go; File pending; int V=10,A=11,S=12;
 public void onCreate(Bundle b){
 super.onCreate(b);
 android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xff101421,0xff242039,0xff141925});
 ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackground(bg);
 LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,45,32,36);scroll.addView(l);
 TextView title=new TextView(this);title.setText("AUTO REVIEW\\nCUTTER");title.setTextColor(0xfff7f5ff);title.setTextSize(30);title.setTypeface(null,1);l.addView(title);
 TextView sub=new TextView(this);sub.setText("STUDIO  •  ANDROID  •  1080P");sub.setTextColor(0xffb9a4ff);sub.setTextSize(12);sub.setPadding(0,8,0,30);l.addView(sub);
 TextView head=new TextView(this);head.setText("01   NGUỒN DỮ LIỆU");head.setTextColor(0xffe9e0ff);head.setTextSize(16);head.setTypeface(null,1);l.addView(head);
 button(l,"＋   THÊM VIDEO NGUỒN",()->pick("video/*",V));
 button(l,"＋   THÊM FILE ÂM THANH",()->pick("audio/*",A));
 counter=new TextView(this);counter.setText("0 video   •   0 audio");counter.setTextColor(0xffd4c9ec);counter.setPadding(0,12,0,25);l.addView(counter);
 TextView spec=new TextView(this);spec.setText("02   THIẾT LẬP XUẤT\\n\\n16:9  •  1920×1080  •  30 FPS\\nMỗi cảnh 4 giây  •  Âm lượng +10 dB\\nH.264 / AAC  •  MP4");spec.setTextColor(0xffe8e2f5);spec.setTextSize(15);spec.setPadding(0,0,0,26);l.addView(spec);
 go=button(l,"▶   BẮT ĐẦU TẠO VIDEO",this::start);
 TextView ph=new TextView(this);ph.setText("03   TIẾN TRÌNH XỬ LÝ");ph.setTextColor(0xffe9e0ff);ph.setTextSize(16);ph.setTypeface(null,1);ph.setPadding(0,28,0,14);l.addView(ph);
 percent=new TextView(this);percent.setText("0%");percent.setTextColor(0xffb9a4ff);percent.setTextSize(32);percent.setTypeface(null,1);l.addView(percent);
 bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(0xffac86ff));l.addView(bar,new LinearLayout.LayoutParams(-1,24));
 stage=new TextView(this);stage.setText("Đang chờ");stage.setTextColor(0xffc8b6f7);stage.setPadding(0,15,0,8);l.addView(stage);
 status=new TextView(this);status.setTextColor(-1);status.setText("Chọn video và audio để bắt đầu");l.addView(status);
 setContentView(scroll);
 }
 Button button(LinearLayout l,String s,Runnable r){
 Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(15);b.setTextColor(0xfff8f4ff);
 android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(0xff59428d);shape.setCornerRadius(24);shape.setStroke(2,0xff9775d5);b.setBackground(shape);
 LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,120);lp.bottomMargin=16;l.addView(b,lp);b.setOnClickListener(v->r.run());return b;
 }
 void progress(int p,String phase){runOnUiThread(()->{bar.setProgress(Math.max(0,Math.min(100,p)));percent.setText(p+"%");stage.setText(phase);});}
 void pick(String type,int req){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType(type);i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,req);}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;try{if(req==S){try(InputStream in=new FileInputStream(pending);OutputStream out=getContentResolver().openOutputStream(data.getData())){byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}say("Đã lưu Review_Final.mp4");return;}ArrayList<Uri> list=new ArrayList<>();if(data.getClipData()!=null)for(int j=0;j<data.getClipData().getItemCount();j++)list.add(data.getClipData().getItemAt(j).getUri());else list.add(data.getData());for(Uri uri:list){File f=new File(getCacheDir(),"input"+System.nanoTime()+(req==V?".mp4":".audio"));try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(f)){byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);} (req==V?videos:audios).add(f);}say("Video: "+videos.size()+" | Audio: "+audios.size());runOnUiThread(()->counter.setText(videos.size()+" video   •   "+audios.size()+" audio"));}catch(Exception e){say("Lỗi đọc/lưu: "+e.getMessage());}}
 void say(String s){runOnUiThread(()->status.setText(s));}
 static String q(File f){return "'"+f.getAbsolutePath().replace("'","'\\''")+"'";}
 void cmd(String args)throws Exception{FFmpegSession s=FFmpegKit.execute(args);if(!ReturnCode.isSuccess(s.getReturnCode()))throw new Exception("FFmpeg thất bại: "+s.getAllLogsAsString());}
 double duration(File f)throws Exception{MediaInformationSession s=FFprobeKit.getMediaInformation(q(f));if(s.getMediaInformation()==null)throw new Exception("Không đọc được thời lượng");return Double.parseDouble(s.getMediaInformation().getDuration());}
 void start(){if(videos.isEmpty()||audios.isEmpty()){say("Cần chọn video và audio");return;}go.setEnabled(false);progress(0,"Chuẩn bị xử lý...");new Thread(()->{try{render();}catch(Exception e){say("Lỗi: "+e.getMessage());}finally{runOnUiThread(()->go.setEnabled(true));}}).start();}
 void render()throws Exception{progress(1,"Đang chuẩn bị dữ liệu...");File dir=new File(getCacheDir(),"work"+System.currentTimeMillis());dir.mkdirs();ArrayList<File> audioParts=new ArrayList<>();for(int i=0;i<audios.size();i++){File out=new File(dir,"a"+i+".wav");cmd("-y -i "+q(audios.get(i))+" -vn -ar 48000 -ac 2 -c:a pcm_s16le "+q(out));audioParts.add(out);progress(2+(int)(10.0*(i+1)/audios.size()),"Chuyển đổi audio "+(i+1)+"/"+audios.size());}File alist=new File(dir,"audio.txt");try(PrintWriter w=new PrintWriter(alist)){for(File f:audioParts)w.println("file "+q(f));}File merged=new File(dir,"Audio_Merged.m4a");say("Đang nối audio...");progress(15,"Đang ghép âm thanh...");cmd("-y -f concat -safe 0 -i "+q(alist)+" -af volume=10dB,alimiter=limit=0.95 -c:a aac -b:a 192k "+q(merged));double total=duration(merged);int n=(int)Math.ceil(total/4);if(n>5000)throw new Exception("Audio quá dài");ArrayList<File> parts=new ArrayList<>();double[] positions=new double[videos.size()];double[] lengths=new double[videos.size()];for(int j=0;j<videos.size();j++)lengths[j]=duration(videos.get(j));for(int i=0;i<n;i++){double seconds=Math.min(4,total-i*4.0);int chosen=-1;for(int j=0;j<videos.size();j++){int k=(i+j)%videos.size();if(lengths[k]>=seconds){chosen=k;break;}}if(chosen<0)throw new Exception("Video nguồn quá ngắn");if(positions[chosen]+seconds>lengths[chosen])positions[chosen]=0;File part=new File(dir,String.format(java.util.Locale.US,"v%05d.mp4",i));cmd(String.format(java.util.Locale.US,"-y -ss %.3f -i %s -t %.3f -an -vf scale=1920:1080:force_original_aspect_ratio=decrease,pad=1920:1080:(ow-iw)/2:(oh-ih)/2,fps=30,format=yuv420p -c:v libx264 -preset ultrafast -crf 23 %s",positions[chosen],q(videos.get(chosen)),seconds,q(part)));positions[chosen]+=seconds+0.3;parts.add(part);final int p=20+(int)((i+1)*70.0/n);progress(p,"Cắt cảnh "+(i+1)+"/"+n);say("Đang cắt cảnh "+(i+1)+"/"+n);}File vlist=new File(dir,"video.txt");try(PrintWriter w=new PrintWriter(vlist)){for(File f:parts)w.println("file "+q(f));}progress(92,"Đang nối các cảnh...");File video=new File(dir,"video.mp4");cmd("-y -f concat -safe 0 -i "+q(vlist)+" -c copy "+q(video));progress(96,"Đang ghép video với âm thanh...");File output=new File(dir,"Review_Final.mp4");cmd(String.format(java.util.Locale.US,"-y -i %s -i %s -map 0:v:0 -map 1:a:0 -c:v copy -c:a aac -t %.3f -movflags +faststart %s",q(video),q(merged),total,q(output)));pending=output;progress(100,"Hoàn thành! Chọn nơi lưu MP4");runOnUiThread(()->{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType("video/mp4");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_TITLE,"Review_Final.mp4");startActivityForResult(intent,S);});}
}